-- Tahap 5: exam reads, attendance integration and cross-domain guards.
SET LOCAL ROLE sim_guru_owner;
CREATE FUNCTION app.exam_read(p_session text,p_date date,p_period uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;operator boolean;BEGIN actor:=app.activity_guard(p_session,false);operator:=app.actor_is_admin() OR app.is_committee(actor,p_date,p_period);
RETURN jsonb_build_object('date',p_date,'admin',app.actor_is_admin(),'canOperate',operator,'required',app.exam_required(p_date,p_period),
'periods',coalesce((SELECT jsonb_agg(to_jsonb(p)||jsonb_build_object('version',version::text) ORDER BY date_start DESC,id) FROM app.exam_periods p WHERE active),'[]'),
'sessions',coalesce((SELECT jsonb_agg(to_jsonb(s)||jsonb_build_object('version',s.version::text) ORDER BY date,time_start,id) FROM app.exam_sessions s WHERE active AND(p_period IS NULL OR period_id=p_period)),'[]'),
'rooms',coalesce((SELECT jsonb_agg(to_jsonb(r)||jsonb_build_object('version',r.version::text,'classIds',coalesce((SELECT jsonb_agg(class_id ORDER BY class_id) FROM app.exam_room_classes WHERE exam_room_id=r.id),'[]')) ORDER BY r.id) FROM app.exam_rooms r JOIN app.exam_sessions s ON s.id=r.session_id WHERE r.active AND s.active AND(p_period IS NULL OR s.period_id=p_period)),'[]'),
'occurrences',coalesce((SELECT jsonb_agg(app.occurrence_dto(o.id)||jsonb_build_object('periodId',app.exam_period_for(o.id),'sourceId',coalesce(o.exam_supervisor_id,o.exam_committee_id),'roomId',(SELECT exam_room_id FROM app.exam_supervisor_assignments WHERE id=o.exam_supervisor_id),'overrideJtm',(SELECT override_jtm::text FROM app.exam_supervisor_assignments WHERE id=o.exam_supervisor_id),'sourceVersion',coalesce((SELECT version::text FROM app.exam_supervisor_assignments WHERE id=o.exam_supervisor_id),(SELECT version::text FROM app.exam_committee_assignments WHERE id=o.exam_committee_id)),'sessionName',o.snapshot->>'sessionName','periodName',o.snapshot->>'periodName','bap', (SELECT to_jsonb(b)||jsonb_build_object('version',version::text) FROM app.exam_baps b WHERE b.occurrence_id=o.id AND state='active'),'lockedBaps',(SELECT count(*) FROM app.exam_baps WHERE occurrence_id=o.id AND state='locked'),'netJtm',coalesce((SELECT sum(jtm) FROM finance.jtm_ledger WHERE occurrence_id=o.id),0)::text) ORDER BY o.time_start,o.id) FROM app.activity_occurrences o JOIN app.activity_assignments a ON a.occurrence_id=o.id WHERE o.kind IN('EXAM_SUPERVISOR','EXAM_COMMITTEE') AND o.removed_at IS NULL AND o.date=p_date AND(p_period IS NULL OR app.exam_period_for(o.id)=p_period) AND(app.actor_is_admin() OR a.effective_user_id=actor OR a.original_user_id=actor OR app.is_committee(actor,o.date,app.exam_period_for(o.id)))),'[]'),
'baps',coalesce((SELECT jsonb_agg(to_jsonb(b)||jsonb_build_object('version',b.version::text,'teacherName',u.full_name,'date',o.date) ORDER BY o.date DESC,b.id) FROM app.exam_baps b JOIN app.activity_occurrences o ON o.id=b.occurrence_id JOIN app.app_users u ON u.id=b.user_id WHERE (p_period IS NULL OR app.exam_period_for(o.id)=p_period) AND(app.actor_is_admin() OR b.user_id=actor OR app.is_committee(actor,o.date,app.exam_period_for(o.id)))),'[]'),
'recaps',coalesce((SELECT jsonb_agg(to_jsonb(q) ORDER BY q."teacherName",q."sourceKind") FROM(SELECT u.full_name AS "teacherName",l.source_kind AS "sourceKind",sum(l.jtm)::numeric(12,4)::text AS jtm FROM finance.jtm_ledger l JOIN app.activity_occurrences o ON o.id=l.occurrence_id JOIN app.app_users u ON u.id=l.user_id WHERE o.kind IN('EXAM_SUPERVISOR','EXAM_COMMITTEE') AND(p_period IS NULL OR app.exam_period_for(o.id)=p_period) AND(app.actor_is_admin() OR l.user_id=actor OR app.is_committee(actor,o.date,app.exam_period_for(o.id))) GROUP BY u.full_name,l.user_id,l.source_kind) q),'[]'),
'teachers',CASE WHEN operator THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',full_name) ORDER BY full_name,id) FROM app.app_users WHERE role='guru' AND status='active'),'[]') ELSE '[]'::jsonb END,
'academicPeriods',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name','Semester '||semester||' · '||date_start) ORDER BY date_start,id) FROM app.academic_periods WHERE archived_at IS NULL),'[]'),
'classes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'periodId',academic_period_id) ORDER BY name,id) FROM app.classes WHERE archived_at IS NULL),'[]'),
'subjects',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name,id) FROM app.subjects WHERE archived_at IS NULL),'[]'));END $$;
-- Extend existing attendance integration, preserving proof validation and tight target precedence.
ALTER FUNCTION app.attendance_participants(date,text) RENAME TO stage4_attendance_participants;
CREATE FUNCTION app.attendance_participants(p_date date,p_type text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ BEGIN IF p_type='KBM' THEN RETURN app.stage4_attendance_participants(p_date,p_type);END IF;
IF p_type<>'UJIAN' OR NOT coalesce((app.day_context_internal(p_date)->>'examEnabled')::boolean,false) THEN RETURN '[]';END IF;RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'name',u.full_name) ORDER BY u.id) FROM app.app_users u WHERE u.role='guru' AND u.status='active' AND(EXISTS(SELECT 1 FROM app.activity_occurrences o JOIN app.activity_assignments a ON a.occurrence_id=o.id WHERE o.date=p_date AND o.removed_at IS NULL AND o.kind IN('EXAM_SUPERVISOR','EXAM_COMMITTEE') AND a.effective_user_id=u.id) OR EXISTS(SELECT 1 FROM finance.jtm_allocations r JOIN app.activity_occurrences o ON o.id=r.occurrence_id WHERE o.kind='EXAM_SUPERVISOR' AND o.removed_at IS NULL AND o.date=p_date AND r.cancelled_at IS NULL AND r.user_id=u.id))),'[]');END $$;
DO $patch$ DECLARE fn regprocedure:='app.attendance_template(text,text,jsonb)'::regprocedure;b text;BEGIN SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;IF strpos(b,'t.sched_type<>''KBM''')=0 THEN RAISE EXCEPTION 'PRIOR_ROUTINE_MISMATCH';END IF;b:=replace(b,'t.sched_type<>''KBM''','t.sched_type NOT IN(''KBM'',''UJIAN'')');b:=replace(b,'sched_time_in=excluded.sched_time_in,sched_time_out=excluded.sched_time_out,version=app.daily_attendance.version+1 WHERE','sched_time_in=least(app.daily_attendance.sched_time_in,excluded.sched_time_in),sched_time_out=greatest(app.daily_attendance.sched_time_out,excluded.sched_time_out),version=app.daily_attendance.version+1 WHERE');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);END $patch$;
ALTER FUNCTION app.students_required(date) RENAME TO stage4_students_required;
CREATE FUNCTION app.students_required(p_date date) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT coalesce(jsonb_agg(v ORDER BY v->>'name',v->>'id'),'[]') FROM(SELECT DISTINCT ON(x->>'id') x v FROM jsonb_array_elements(app.stage4_students_required(p_date)||app.exam_required(p_date)) x ORDER BY x->>'id') q $$;
CREATE FUNCTION app.committee_target(p_actor uuid,p_target uuid,p_date date) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM app.activity_occurrences o JOIN app.activity_assignments a ON a.occurrence_id=o.id WHERE o.removed_at IS NULL AND o.date=p_date AND o.kind='EXAM_SUPERVISOR' AND a.effective_user_id=p_target AND app.is_committee(p_actor,p_date,app.exam_period_for(o.id),true)) $$;
DO $patch$ DECLARE fn regprocedure; b text;BEGIN
fn:='app.attendance_command(text,text,jsonb)'::regprocedure;SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;
b:=replace(b,'AND NOT app.is_piket(a,d.date))','AND NOT app.is_piket(a,d.date) AND NOT app.committee_target(a,d.user_id,d.date))');
b:=replace(b,' IF NOT app.actor_is_admin() AND app.is_duty_target', ' IF NOT app.actor_is_admin() AND EXISTS(SELECT 1 FROM app.activity_occurrences o JOIN app.activity_assignments x ON x.occurrence_id=o.id WHERE o.kind=''EXAM_COMMITTEE'' AND o.removed_at IS NULL AND o.date=d.date AND x.effective_user_id=d.user_id) THEN RAISE EXCEPTION ''FORBIDDEN'' USING ERRCODE=''42501'';END IF; IF NOT app.actor_is_admin() AND app.is_duty_target');
b:=replace(b,$str$WHEN d.user_id<>a THEN 'piket'$str$,$str$WHEN d.user_id<>a AND app.committee_target(a,d.user_id,d.date) THEN 'committee' WHEN d.user_id<>a THEN 'piket'$str$);EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);
fn:='app.students_save(text,jsonb)'::regprocedure;SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;b:=replace(b,'AND NOT app.is_piket(a,d) THEN','AND NOT app.is_piket(a,d) AND NOT app.is_committee(a,d,NULL,true) THEN');b:=replace(b,' IF c.id IS NULL OR',' IF NOT app.actor_is_admin() AND NOT app.is_piket(a,d) AND NOT EXISTS(SELECT 1 FROM app.exam_room_classes rc JOIN app.exam_rooms exr ON exr.id=rc.exam_room_id JOIN app.exam_sessions exs ON exs.id=exr.session_id WHERE rc.class_id=c.id AND exr.active AND exs.active AND exs.date=d AND app.is_committee(a,d,exs.period_id,true)) THEN RAISE EXCEPTION ''FORBIDDEN'' USING ERRCODE=''42501'';END IF; IF c.id IS NULL OR');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);
fn:='app.activity_read(text,text,jsonb)'::regprocedure;SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;
b:=replace(b,'app.is_piket(a,app.activity_today())','(app.is_piket(a,app.activity_today()) OR app.is_committee(a,app.activity_today(),NULL,true))');b:=replace(b,'AND NOT app.is_piket(a,d) THEN','AND NOT app.is_piket(a,d) AND NOT app.is_committee(a,d,NULL,true) THEN');b:=replace(b,'OR app.is_piket(a,x.date))','OR app.is_piket(a,x.date) OR app.committee_target(a,x.user_id,x.date))');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);
fn:='app.occurrence_command(text,uuid,text,bigint,text)'::regprocedure;SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;b:=replace(b,$str$ IF o.id IS NULL$str$, $str$ IF o.kind IN('EXAM_SUPERVISOR','EXAM_COMMITTEE','EVENT') THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';END IF; IF o.id IS NULL$str$);EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);
END $patch$;
ALTER TABLE app.daily_attendance DROP CONSTRAINT daily_attendance_time_in_source_check;
ALTER TABLE app.daily_attendance ADD CONSTRAINT daily_attendance_time_in_source_check CHECK(time_in_source IN('admin','self','piket','committee'));
CREATE FUNCTION app.exam_parent_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
IF TG_TABLE_NAME='academic_periods' THEN IF EXISTS(SELECT 1 FROM app.exam_periods WHERE academic_period_id=OLD.id AND active AND(NEW.archived_at IS NOT NULL OR date_start<NEW.date_start OR date_end>NEW.date_end)) THEN RAISE EXCEPTION 'MASTER_REFERENCED' USING ERRCODE='23503';END IF;END IF;
IF TG_TABLE_NAME='classes' THEN IF EXISTS(SELECT 1 FROM app.exam_room_classes rc JOIN app.exam_rooms r ON r.id=rc.exam_room_id WHERE rc.class_id=OLD.id AND r.active) AND(NEW.archived_at IS NOT NULL OR NEW.academic_period_id<>OLD.academic_period_id) THEN RAISE EXCEPTION 'MASTER_REFERENCED' USING ERRCODE='23503';END IF;END IF;
IF TG_TABLE_NAME='subjects' THEN IF NEW.archived_at IS NOT NULL AND EXISTS(SELECT 1 FROM app.exam_rooms WHERE subject_id=OLD.id AND active) THEN RAISE EXCEPTION 'MASTER_REFERENCED' USING ERRCODE='23503';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER exam_period_parent BEFORE UPDATE ON app.academic_periods FOR EACH ROW EXECUTE FUNCTION app.exam_parent_guard();
CREATE TRIGGER exam_class_parent BEFORE UPDATE ON app.classes FOR EACH ROW EXECUTE FUNCTION app.exam_parent_guard();
CREATE TRIGGER exam_subject_parent BEFORE UPDATE ON app.subjects FOR EACH ROW EXECUTE FUNCTION app.exam_parent_guard();
-- Teaching edits must also respect dated exam assignments.
CREATE FUNCTION app.exam_schedule_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NEW.state='archived' THEN RETURN NEW;END IF;
IF EXISTS(SELECT 1 FROM app.activity_occurrences o JOIN app.activity_assignments a ON a.occurrence_id=o.id LEFT JOIN app.exam_committee_assignments c ON c.id=o.exam_committee_id WHERE o.removed_at IS NULL AND o.date BETWEEN NEW.valid_from AND NEW.valid_to AND extract(dow FROM o.date)=NEW.day_index AND a.effective_user_id=NEW.user_id AND(o.kind='EXAM_SUPERVISOR' OR(o.kind='EXAM_COMMITTEE' AND c.exclusive_time_start IS NOT NULL)) AND o.time_start<NEW.time_end AND o.time_end>NEW.time_start) OR EXISTS(SELECT 1 FROM finance.jtm_allocations r JOIN app.activity_occurrences o ON o.id=r.occurrence_id WHERE o.kind='EXAM_SUPERVISOR' AND o.removed_at IS NULL AND r.cancelled_at IS NULL AND r.user_id=NEW.user_id AND o.date BETWEEN NEW.valid_from AND NEW.valid_to AND extract(dow FROM o.date)=NEW.day_index AND o.time_start<NEW.time_end AND o.time_end>NEW.time_start) THEN RAISE EXCEPTION 'SCHEDULE_COLLISION' USING ERRCODE='23505';END IF;RETURN NEW;END $$;
CREATE TRIGGER exam_schedule BEFORE INSERT OR UPDATE ON app.teaching_schedules FOR EACH ROW EXECUTE FUNCTION app.exam_schedule_guard();

DO $patch$ DECLARE fn regprocedure;b text;BEGIN
fn:='app.stage4_attendance_participants(date,text)'::regprocedure;SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;b:=replace(b,'WHERE o.date=p_date','WHERE o.kind IN(''KBM'',''PIKET'',''UPACARA'') AND o.removed_at IS NULL AND o.date=p_date');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);
fn:='app.duty_read(text,date)'::regprocedure;SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;b:=replace(b,'WHERE o.date=p_date','WHERE o.kind IN(''KBM'',''PIKET'',''UPACARA'') AND o.date=p_date');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);
fn:='app.calendar_preview(text,text,jsonb)'::regprocedure;SELECT prosrc INTO b FROM pg_proc WHERE oid=fn;b:=replace(b,'''attendance_ready''','''exams_ready''');EXECUTE split_part(pg_get_functiondef(fn),'$function$',1)||quote_literal(b);
END $patch$;
CREATE OR REPLACE FUNCTION finance.conservation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE v_occ uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.occurrence_id ELSE NEW.occurrence_id END;s numeric;a numeric;r numeric;BEGIN SELECT scheduled_jtm INTO s FROM app.activity_occurrences WHERE id=v_occ;a:=app.jtm_basis(v_occ);SELECT coalesce(sum(allocated_jtm),0) INTO r FROM finance.jtm_allocations WHERE occurrence_id=v_occ AND cancelled_at IS NULL;IF a+r>s THEN RAISE EXCEPTION 'CONSERVATION_VIOLATION' USING ERRCODE='22023';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER adjustment_delete_conservation AFTER DELETE ON finance.jtm_adjustments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance.conservation_guard();
CREATE FUNCTION app.exam_duty_schedule_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NEW.kind='UPACARA' AND NEW.active AND EXISTS(SELECT 1 FROM app.activity_occurrences o JOIN app.activity_assignments a ON a.occurrence_id=o.id LEFT JOIN app.exam_committee_assignments c ON c.id=o.exam_committee_id WHERE o.removed_at IS NULL AND o.date=NEW.date AND a.effective_user_id=NEW.user_id AND(o.kind='EXAM_SUPERVISOR' OR(o.kind='EXAM_COMMITTEE' AND c.exclusive_time_start IS NOT NULL)) AND o.time_start<NEW.time_end AND o.time_end>NEW.time_start) THEN RAISE EXCEPTION 'DUTY_COLLISION' USING ERRCODE='23505';END IF;RETURN NEW;END $$;
CREATE TRIGGER exam_duty_schedule BEFORE INSERT OR UPDATE ON app.duty_schedules FOR EACH ROW EXECUTE FUNCTION app.exam_duty_schedule_guard();

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app,finance FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.exam_read(text,date,uuid),app.exam_save(text,jsonb),app.exam_delete(text,jsonb),app.exam_bap_save(text,jsonb),app.duty_preview(text,jsonb) TO sim_guru_business;
RESET ROLE;
